1	"use client";
2	
3	import { useState, type ReactNode } from "react";
4	
5	// Base tab order. "Manage" (the game control panel) is injected right after
6	// Overview for game servers only — see `tabs` below.
7	const BASE_TABS = [
8	  "Overview",
9	  "Control panel",
10	  "Metrics",
11	  "Console",
12	  "Files",
13	  "Snapshots",
14	  "Backups",
15	  "Networking",
16	  "Resize",
17	  "Activity",
18	] as const;
19	
20	// Customer-facing label overrides. The internal tab key stays "resize" so the
21	// ?tab=resize deep-links, the panels map and every internal reference keep
22	// working untouched — only the text the customer reads changes to "Upgrade".
23	const TAB_LABELS: Record<string, string> = {
24	  resize: "Upgrade",
25	};
26	
27	export function ServerTabs({
28	  initialTab,
29	  overview,
30	  manage,
31	  mods,
32	  controlPanel,
33	  metrics,
34	  console: consolePanel,
35	  files,
36	  snapshots,
37	  backups,
38	  networking,
39	  resize,
40	  activity,
41	}: {
42	  initialTab?: string;
43	  overview: ReactNode;
44	  /** Game control panel — present (and shown as "Manage") for game servers only. */
45	  manage?: ReactNode;
46	  /** Mod/plugin manager — present ("Mods") for game servers only. */
47	  mods?: ReactNode;
48	  controlPanel: ReactNode;
49	  metrics: ReactNode;
50	  console: ReactNode;
51	  files: ReactNode;
52	  snapshots: ReactNode;
53	  backups: ReactNode;
54	  networking: ReactNode;
55	  resize: ReactNode;
56	  activity: ReactNode;
57	}) {
58	  // Game-only tabs are injected right after Overview, in order.
59	  const extra: string[] = [];
60	  if (manage) extra.push("Manage");
61	  if (mods) extra.push("Mods");
62	  const TABS: readonly string[] = extra.length ? ["Overview", ...extra, ...BASE_TABS.slice(1)] : BASE_TABS;
63	  const keys = TABS.map((t) => t.toLowerCase());
64	  const [tab, setTab] = useState<string>(
65	    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview"
66	  );
67	
68	  const panels: Record<string, ReactNode> = {
69	    overview,
70	    manage,
71	    mods,
72	    "control panel": controlPanel,
73	    metrics,
74	    console: consolePanel,
75	    files,
76	    snapshots,
77	    backups,
78	    networking,
79	    resize,
80	    activity,
81	  };
82	
83	  return (
84	    <div>
85	      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
86	        {TABS.map((t) => {
87	          const k = t.toLowerCase();
88	          const active = tab === k;
89	          return (
90	            <button
91	              key={k}
92	              type="button"
93	              onClick={() => {
94	                setTab(k);
95	                window.history.replaceState(null, "", `?tab=${k}`);
96	              }}
97	              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
98	                active
99	                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
100	                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
101	              }`}
102	            >
103	              {TAB_LABELS[k] ?? t}
104	            </button>
105	          );
106	        })}
107	      </div>
108	      <div className="animate-fade-up">{panels[tab]}</div>
109	    </div>
110	  );
111	}
