31	  --animate-fade-up: fade-up 0.4s ease-out both;
32	  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;
33	
34	  /* Admin attention indicators (components/admin/AdminIndicators.tsx). `bell-shake`
35	     runs once whenever a new ticket / live-chat reply / email arrives; opt-in via
36	     `motion-safe:` at the call site so reduced-motion users just see the badge. */
37	  --animate-bell-shake: bell-shake 0.9s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
38	  @keyframes bell-shake {
39	    0%, 100% { transform: rotate(0); }
40	    10%, 50%, 90% { transform: rotate(-11deg); }
41	    30%, 70% { transform: rotate(11deg); }
42	  }
43	
44	  /* Pricing explorer interactions. `price-pop` runs on every billing-cycle change
45	     (re-keyed number), `panel-in` on every product-tab switch. Both are opt-in via
46	     `motion-safe:` at the call site, so reduced-motion users see the resting frame. */
47	  --animate-price-pop: price-pop 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
48	  --animate-panel-in: panel-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
49	
50	  @keyframes price-pop {
51	    from { opacity: 0; transform: translateY(7px); filter: blur(3px); }
52	    to { opacity: 1; transform: translateY(0); filter: blur(0); }
53	  }
54	  @keyframes panel-in {
55	    from { opacity: 0; transform: translateY(12px) scale(0.994); }
56	    to { opacity: 1; transform: translateY(0) scale(1); }
57	  }
58	  /* GameHero logo entrance — a soft pop as the themed hero mounts. Applied via
59	     the `motion-safe:animate-gh-pop` utility so reduced-motion users see no motion. */
60	  @keyframes gh-pop {
61	    from { opacity: 0; transform: translateY(10px) scale(0.9); }
62	    to { opacity: 1; transform: translateY(0) scale(1); }
63	  }
64	  --animate-gh-pop: gh-pop 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
65	
66	  /* Showcase mock-screen animations (marketing product pages). All are opt-in
67	     via Tailwind's `motion-safe:` variant, so reduced-motion users see the final
68	     resting state (bars full, lines visible) with no motion. */
69	  --animate-grow-up: grow-up 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
70	  --animate-grow-x: grow-x 1.1s cubic-bezier(0.22, 1, 0.36, 1) both;
71	  --animate-eq: eq 1.7s ease-in-out infinite;
72	  --animate-blink: blink 1.1s steps(1) infinite;
73	  --animate-sweep: sweep 3.4s ease-in-out infinite;
74	  --animate-line-in: line-in 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
75	
76	  @keyframes fade-up {
77	    from { opacity: 0; transform: translateY(8px); }
78	    to { opacity: 1; transform: translateY(0); }
79	  }
80	  @keyframes pulse-dot {
81	    0%, 100% { box-shadow: 0 0 0 0 rgb(52 211 153 / 0.5); }
82	    50% { box-shadow: 0 0 0 5px rgb(52 211 153 / 0); }
83	  }
84	  /* One-shot bar grow (origin at the base). Resting state = full. */
85	  @keyframes grow-up {
86	    from { transform: scaleY(0.06); }
87	    to { transform: scaleY(1); }
88	  }
89	  /* One-shot progress/usage fill. Resting state = full width. */
90	  @keyframes grow-x {
91	    from { transform: scaleX(0); }
92	    to { transform: scaleX(1); }
93	  }
94	  /* Continuous "live traffic" equaliser pulse. Resting state = full height. */
95	  @keyframes eq {
96	    0%, 100% { transform: scaleY(0.35); }
97	    50% { transform: scaleY(1); }
98	  }
99	  /* Terminal cursor blink. Resting state = visible. */
100	  @keyframes blink {
101	    0%, 49% { opacity: 1; }
102	    50%, 100% { opacity: 0; }
103	  }
104	  /* Soft light sweep across a chart/highlight. */
105	  @keyframes sweep {
106	    0% { transform: translateX(-120%); opacity: 0; }
107	    40%, 60% { opacity: 0.7; }
108	    100% { transform: translateX(320%); opacity: 0; }
109	  }
110	  /* Staggered line/row reveal. Resting state = visible. */
111	  @keyframes line-in {
112	    from { opacity: 0; transform: translateY(6px); }
113	    to { opacity: 1; transform: translateY(0); }
114	  }
115	}
