333	     heroes previously inlined by hand. Sits in an absolutely-positioned layer. */
334	  .hero-aura {
335	    background-image:
336	      radial-gradient(ellipse 70% 60% at 15% 0%, rgb(111 71 245 / 0.20), transparent 70%),
337	      radial-gradient(ellipse 60% 50% at 90% 10%, rgb(59 130 246 / 0.14), transparent 70%);
338	  }
339	
340	  /* Soft violet lift on hover for interactive cards (was inline arbitrary shadow). */
341	  .lift {
342	    @apply transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30;
343	    &:hover { box-shadow: 0 18px 40px -20px rgb(111 71 245 / 0.45); }
344	  }
345	
346	  /* Consistent max-width content rail. */
347	  .rail {
348	    @apply mx-auto max-w-6xl px-5 sm:px-6;
349	  }
350	
351	  /* Top-nav dropdown trigger button. */
352	  .nav-trigger {
353	    @apply inline-flex cursor-pointer items-center gap-1 rounded-lg px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:text-white;
354	  }
355	  .nav-trigger.is-open {
356	    @apply text-white;
357	  }
358	
359	  /* Animated gradient underline that wipes in on hover (rocket-style nav). Sits
360	     inside the px-3 padding so it tracks the label width. */
361	  .nav-underline {
362	    position: relative;
363	  }
364	  .nav-underline::after {
365	    content: "";
366	    position: absolute;
367	    left: 12px;
368	    right: 12px;
369	    bottom: 5px;
370	    height: 1.5px;
371	    border-radius: 2px;
372	    background: linear-gradient(90deg, var(--color-accent-blue), var(--color-brand-400));
373	    transform: scaleX(0);
374	    transform-origin: left center;
375	    transition: transform 0.28s cubic-bezier(0.4, 0, 0.2, 1);
376	  }
377	  .nav-underline:hover::after,
378	  .nav-underline:focus-visible::after,
379	  .nav-underline.is-open::after {
380	    transform: scaleX(1);
381	  }
382	  @media (prefers-reduced-motion: reduce) {
383	    .nav-underline::after { transition: none; }
384	  }
385	}
